"""Generate the draft adapter envelope schema; ingestion enforces relational invariants."""
import json
from pathlib import Path
string={'type':'string'}; sha={'type':'string','pattern':'^[0-9a-f]{64}$'}; integer={'type':'integer','minimum':0}
def obj(props):return {'type':'object','required':list(props),'additionalProperties':False,'properties':props}
span=obj({k:integer for k in ['byte_start','byte_end','line_start','line_end','column_start_bytes','column_end_bytes']})
definition={'id':sha,'path':string,'source_sha256':sha,'symbol':string,'kind':string,'span':span,'metrics':obj({'cyclomatic_complexity':{'type':'integer','minimum':1},'physical_lines':{'type':'integer','minimum':1}}),'snippet_sha256':sha}
props={'schema_version':{'const':'evolution.findings/0.1'},'purpose':{'const':'feasibility_probe'},'admitted':{'const':False},'repository':string,'commit':{'type':'string','pattern':'^[0-9a-f]{40}$'},'language':{'enum':['python','java','c','cpp']},'rule_id':{'const':'experimental.cc.named-definition.v0'},'archive_sha256':sha,'scope':{'type':'object'},'scope_sha256':sha,'tool':obj({'adapter_sha256':sha,'tree_sitter':string,'grammar':string}),'status':obj({'syntax':{'enum':['complete','partial','not_applicable']},'semantic':{'const':'not_evaluated'},'build':{'const':'not_evaluated'},'runtime':{'const':'not_evaluated'},'native_preprocessing':{'enum':['not_evaluated','not_applicable']}}),'inventory':{'type':'array','items':obj({'path':string,'sha256':sha,'bytes':integer,'physical_lines':integer,'parse_status':{'enum':['complete','failed']}})},'excluded':{'type':'array','items':obj({'path':string,'reason':string})},'diagnostics':{'type':'array','items':obj({'path':string,'line':integer,'byte_start':integer,'byte_end':integer,'kind':string})},'definitions':{'type':'array','items':obj(definition)},'findings':{'type':'array','items':obj({'rule_id':string,'concept':string,'language':string,'severity':string,'threshold':obj({'operator':{'const':'>'},'value':{'const':10}}),**definition})},'summary':obj({'eligible_files':integer,'parsed_files':integer,'definition_count':integer,'finding_count':integer,'prevalence':{'type':['number','null'],'minimum':0,'maximum':1},'physical_lines':integer,'sensitivity_counts':obj({str(t):integer for t in [10,15,20]})}),'limitations':{'type':'array','items':string}}
schema={'$schema':'https://json-schema.org/draft/2020-12/schema',**obj(props)}
Path(__file__).with_name('findings.schema.json').write_text(json.dumps(schema,indent=2)+'\n')
